#ifndef HIBR_HTMLENT_H
#define HIBR_HTMLENT_H

#include <stddef.h>

/* The HTML5 named character references, mods/htmlent.c, generated by
   tools/htmlents.py from WHATWG's entities.json and compiled into both the
   html and the md module (Gitea #355). he_find takes a name without its &
   and ;, exactly len bytes, and answers the characters it stands for, or 0;
   legacy, when given, says whether the name is also recognised with no
   semicolon, which HTML honours and CommonMark does not. */
extern const char he_blob[];
extern const unsigned short he_off[];
extern const size_t he_n;

const char *he_find(const char *nm, size_t len, int *legacy);

#endif
